    dqdc[5] = 6 * q_nocor;
    dqdc[6] = q_nocor;
    dqdc[7] = q_nocor;
    dqdc[8] = q_nocor;
    dqdc[9] = 2 * q_nocor;
    dqdc[10] = 1.5 * q_nocor + k_f * sc[2];
