  dqdci = +k_f * sc[3] * sc[3];
  J[19] -= dqdci; // dwdot[H]/d[H]
  J[21] -= dqdci; // dwdot[O2]/d[H]
  J[24] += dqdci; // dwdot[HO2]/d[H]
