    dqdci = (2 - 1) * q_nocor;
    J[163] += dqdci; // dwdot[H]/d[CH4]
    J[172] += dqdci; // dwdot[CO]/d[CH4]
    J[174] -= dqdci; // dwdot[HCO]/d[CH4]
