  wdot[0] -= q; // H2
  wdot[1] += q; // H
  wdot[2] -= q; // O
  wdot[4] += q; // OH
  // d()/d[H2]
  dqdci = +k_f * sc[2];
  J[0] -= dqdci; // dwdot[H2]/d[H2]
  J[1] += dqdci; // dwdot[H]/d[H2]
  J[2] -= dqdci; // dwdot[O]/d[H2]
  J[4] += dqdci; // dwdot[OH]/d[H2]
  // d()/d[H]
  dqdci = -k_r * sc[4];
  J[18] -= dqdci; // dwdot[H2]/d[H]
  J[19] += dqdci; // dwdot[H]/d[H]
  J[20] -= dqdci; // dwdot[O]/d[H]
  J[22] += dqdci; // dwdot[OH]/d[H]
  // d()/d[O]
  dqdci = +k_f * sc[0];
  J[36] -= dqdci; // dwdot[H2]/d[O]
  J[37] += dqdci; // dwdot[H]/d[O]
  J[38] -= dqdci; // dwdot[O]/d[O]
